function updateHotspots(){ if(!model)return; const rect=stage.getBoundingClientRect(); hotspotData.forEach(hotspot=>{ const position=model.localToWorld(new THREE.Vector3(Number(hotspot.x),Number(hotspot.y),Number(hotspot.z))).project(camera); const visible=position.z<1&&position.z>-1; hotspot.marker.style.display=visible?'flex':'none'; hotspot.marker.style.left=((position.x+1)/2*rect.width)+'px'; hotspot.marker.style.top=((-position.y+1)/2*rect.height)+'px'; }); }
