function meshMaterials(){ return modelParts.flatMap(part=>Array.isArray(part.material)?part.material:[part.material]); }
function focusObject(object){ if(!object)return; const box=new THREE.Box3().setFromObject(object), center=box.getCenter(new THREE.Vector3()), size=box.getSize(new THREE.Vector3()), distance=Math.max(size.x,size.y,size.z)*2.2; camera.position.copy(center).add(new THREE.Vector3(distance*.8,distance*.6,distance)); controls.target.copy(center); controls.update(); }
function standardView(axis){ if(!model)return; const box=new THREE.Box3().setFromObject(model), center=box.getCenter(new THREE.Vector3()), size=box.getSize(new THREE.Vector3()), distance=Math.max(size.x,size.y,size.z)*2.4; const positions={front:new THREE.Vector3(0,0,distance),top:new THREE.Vector3(0,distance,0),side:new THREE.Vector3(distance,0,0)}; camera.position.copy(center).add(positions[axis]); controls.target.copy(center); controls.update(); }
