function readablePartName(mesh, index){ const clean=value=>String(value||'').replace(/^(object|mesh|node|primitive|geometry)[_.\- ]*\d*$/i,'').replace(/[_.\-]+/g,' ').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/\s+/g,' ').trim(); const meshName=clean(mesh.name); const materialName=clean(mesh.material?.name); const parentName=clean(mesh.parent?.name); const generic=!meshName || /^(cube|sphere|cylinder|plane|circle|box|shape)\s*\d*$/i.test(meshName); const label=generic ? (materialName || parentName || `Part ${index+1}`) : meshName; return label.replace(/\b\w/g, letter=>letter.toUpperCase()); }
function listParts(){ modelParts=[]; model.traverse(o=>{ if(o.isMesh){ o.userData.baseColor=o.material.color?.clone(); o.userData.displayName=readablePartName(o,modelParts.length); modelParts.push(o); }}); document.querySelector('#part-count').textContent=modelParts.length; partsEl.innerHTML=modelParts.map((m,i)=>`<button data-part="${i}" class="part flex w-full items-center justify-between rounded-xl px-3 py-2 text-left text-sm text-slate-400 hover:bg-white/5"><span>${m.userData.displayName}</span><span class="text-[10px] text-slate-600">${m.material?.name && !/^material[_.\-]?\d*$/i.test(m.material.name) ? m.material.name : 'surface'}</span></button>`).join(''); partsEl.querySelectorAll('.part').forEach((b,i)=>b.onclick=()=>select(modelParts[i],b)); }
function setMeshHighlight(mesh, active){ if(!mesh?.material)return; const materials=Array.isArray(mesh.material)?mesh.material:[mesh.material]; mesh.userData.baseEmissives ??= materials.map(material=>({ color:material.emissive?.clone(), intensity:material.emissiveIntensity ?? 1 })); materials.forEach((material,index)=>{ if(!material.emissive)return; if(active){ material.emissive.set(0x22d3ee); material.emissiveIntensity=.45; } else { const base=mesh.userData.baseEmissives[index]; if(base.color)material.emissive.copy(base.color); material.emissiveIntensity=base.intensity; } }); }
function updateSelectionStatus(){ const status=document.querySelector('#selection-status'); if(status)status.textContent=selectedParts.length+' part'+(selectedParts.length===1?'':'s')+' selected'; }
function select(mesh, button){ if(!mesh)return; selectedParts.forEach(part=>setMeshHighlight(part,false)); selectedParts=[mesh]; setMeshHighlight(mesh,true); partsEl.querySelectorAll('.part').forEach(b=>b.classList.remove('mesh-active')); button?.classList.add('mesh-active'); selectionHelper.setFromObject(mesh); selectionHelper.visible=true; updateSelectionStatus(); }
function selectAll(){ selectedParts.forEach(part=>setMeshHighlight(part,false)); selectedParts=[...modelParts]; selectedParts.forEach(part=>setMeshHighlight(part,true)); selectionHelper.visible=false; partsEl.querySelectorAll('.part').forEach(b=>b.classList.add('mesh-active')); updateSelectionStatus(); }
function deselectAll(){ selectedParts.forEach(part=>setMeshHighlight(part,false)); selectedParts=[]; selectionHelper.visible=false; partsEl.querySelectorAll('.part').forEach(b=>b.classList.remove('mesh-active')); updateSelectionStatus(); }
function addSelectionControls(){ const controls=document.createElement('div'); controls.className='mb-2 space-y-2'; controls.innerHTML='<div class="flex items-center justify-between"><span id="selection-status" class="text-xs text-cyan-300">No parts selected</span><button type="button" class="deselect-parts text-[11px] text-slate-500 hover:text-white">Deselect</button></div><input type="search" placeholder="Search parts..." class="part-search w-full rounded-xl border border-white/10 bg-black/20 px-3 py-2 text-xs text-white outline-none placeholder:text-slate-600 focus:border-cyan-300/50"><button type="button" class="select-all-parts w-full rounded-lg bg-white/10 px-2 py-2 text-[11px] text-slate-300 hover:bg-cyan-300/20">Select all parts</button>'; partsEl.prepend(controls); controls.querySelector('.select-all-parts').onclick=selectAll; controls.querySelector('.deselect-parts').onclick=deselectAll; controls.querySelector('.part-search').oninput=event=>{ const query=event.target.value.toLowerCase(); partsEl.querySelectorAll('.part').forEach(button=>button.classList.toggle('hidden',!button.textContent.toLowerCase().includes(query))); }; }
function selectedMaterials(){ return selectedParts.flatMap(part=>Array.isArray(part.material)?part.material:[part.material]); }
function captureOriginalAppearance(){ modelParts.forEach(part=>{ part.userData.originalPosition=part.position.clone(); part.userData.explodeDirection=part.position.clone().add(new THREE.Vector3(.1,.1,.1)).normalize(); const materials=Array.isArray(part.material)?part.material:[part.material]; materials.forEach(material=>{ material.userData.originalColor=material.color?.clone(); material.userData.originalMap=material.map; }); }); }
function applyTexture(texture,url){ selectedMaterials().forEach(material=>{ material.map=texture; material.userData.appliedTextureUrl=url; material.needsUpdate=true; }); }
window.applyModelTexture=(url,name)=>{ if(!selectedParts.length){ alert('Select one or more model parts first.'); return; } new THREE.TextureLoader().load(url,t=>{ t.colorSpace=THREE.SRGBColorSpace; t.wrapS=t.wrapT=THREE.RepeatWrapping; applyTexture(t,url); materialsPanel.querySelector('#texture-status').textContent='Applied: '+name; }, undefined, error=>console.error('Texture could not be loaded',error)); };
materialsPanel.querySelector('#apply-texture').onclick=()=>{ if(pendingTexture)window.applyModelTexture(pendingTexture.url,pendingTexture.name); };
function applyVariant(variant){ const parts=variant?.configuration?.parts||{}; Object.entries(parts).forEach(([index,state])=>{ const part=modelParts[Number(index)]; if(!part)return; const materials=Array.isArray(part.material)?part.material:[part.material]; materials.forEach(material=>{ if(state.color&&material.color)material.color.set(state.color); if(state.texture)new THREE.TextureLoader().load(state.texture,texture=>{ texture.colorSpace=THREE.SRGBColorSpace; texture.wrapS=texture.wrapT=THREE.RepeatWrapping; material.map=texture; material.userData.appliedTextureUrl=state.texture; material.needsUpdate=true; }); }); }); variantPanel.querySelector('#variant-status').textContent='Applied'; }
variantPanel.querySelector('#apply-variant').onclick=()=>{ if(pendingVariant)applyVariant(pendingVariant); };
materialsPanel.querySelector('#texture-search').oninput=event=>{ const query=event.target.value.toLowerCase(); textureLibraryEl.querySelectorAll('.texture-option').forEach(button=>button.classList.toggle('hidden',!button.textContent.toLowerCase().includes(query))); };
materialsPanel.querySelector('#texture-scale').oninput=event=>{ const scale=Number(event.target.value); selectedMaterials().forEach(material=>{ if(material.map)material.map.repeat.set(scale,scale); }); };
materialsPanel.querySelector('#clear-applied-texture').onclick=()=>{ selectedMaterials().forEach(material=>{ material.map=null; material.needsUpdate=true; }); materialsPanel.querySelector('#texture-status').textContent='Texture cleared'; };
materialsPanel.querySelector('#reset-appearance').onclick=()=>{ modelParts.forEach(part=>{ const materials=Array.isArray(part.material)?part.material:[part.material]; materials.forEach(material=>{ if(material.userData.originalColor)material.color.copy(material.userData.originalColor); material.map=material.userData.originalMap||null; material.needsUpdate=true; }); }); pendingTexture=null; materialsPanel.querySelector('#texture-status').textContent='Appearance reset'; };
new GLTFLoader().load(@json($modelUrl), async gltf=>{ model=gltf.scene; const box=new THREE.Box3().setFromObject(model), center=box.getCenter(new THREE.Vector3()), size=box.getSize(new THREE.Vector3()), scale=2.5/Math.max(size.x,size.y,size.z); model.scale.setScalar(scale); model.position.sub(center.multiplyScalar(scale)); scene.add(model); listParts(); captureOriginalAppearance(); addSelectionControls(); const hashConfig=window.location.hash.startsWith('#config=')?decodeConfiguration(window.location.hash.slice(8)):null; const localConfig=JSON.parse(localStorage.getItem('model-config-{{ $item->slug }}')||'null'); const queryToken=new URLSearchParams(window.location.search).get('configuration'); const savedConfig=queryToken?await loadServerConfiguration(queryToken):null; restoreConfiguration(savedConfig?.configuration||hashConfig||localConfig); }, undefined, e=>{ partsEl.innerHTML='<p class="px-3 py-2 text-sm text-rose-300">Could not load this GLB file.</p>'; console.error(e); });
stage.addEventListener('pointerdown', e=>{ if(!model)return; const rect=renderer.domElement.getBoundingClientRect(); pointer.x=((e.clientX-rect.left)/rect.width)*2-1; pointer.y=-((e.clientY-rect.top)/rect.height)*2+1; raycaster.setFromCamera(pointer,camera); const hit=raycaster.intersectObject(model,true)[0]; if(hit){ const index=modelParts.indexOf(hit.object); select(hit.object,partsEl.querySelector(`[data-part="${index}"]`)); } });
stage.addEventListener('click', e=>{ if(!measureMode||!model||e.target.closest('button'))return; const rect=renderer.domElement.getBoundingClientRect(); pointer.x=((e.clientX-rect.left)/rect.width)*2-1; pointer.y=-((e.clientY-rect.top)/rect.height)*2+1; raycaster.setFromCamera(pointer,camera); const hit=raycaster.intersectObject(model,true)[0]; if(!hit)return; if(measurePoints.length===2){ measurePoints=[]; measureGroup.clear(); } measurePoints.push(hit.point.clone()); if(measurePoints.length===2){ const distance=measurePoints[0].distanceTo(measurePoints[1]); const geometry=new THREE.BufferGeometry().setFromPoints(measurePoints); const line=new THREE.Line(geometry,new THREE.LineBasicMaterial({color:0xfbbf24,depthTest:false})); line.renderOrder=20; measureGroup.add(line); measureLabel.textContent='Distance: '+distance.toFixed(3)+' model units'; measureLabel.classList.remove('hidden'); } });
function updateMeasurementLabel(){ if(measurePoints.length!==2)return; const midpoint=measurePoints[0].clone().lerp(measurePoints[1],.5).project(camera); const rect=stage.getBoundingClientRect(); measureLabel.style.left=((midpoint.x+1)/2*rect.width)+'px'; measureLabel.style.top=((-midpoint.y+1)/2*rect.height)+'px'; }
viewerTools.querySelector('#measure-model').onclick=event=>{ measureMode=!measureMode; event.currentTarget.classList.toggle('bg-amber-300/20',measureMode); event.currentTarget.textContent=measureMode?'Click two points':'Measure'; if(!measureMode){ measurePoints=[]; measureGroup.clear(); measureLabel.classList.add('hidden'); } };
quoteButton.onclick=()=>{ quoteModal.classList.remove('hidden'); quoteModal.classList.add('flex'); };
quoteModal.querySelector('.close-quote').onclick=()=>{ quoteModal.classList.add('hidden'); quoteModal.classList.remove('flex'); };
quoteModal.querySelector('form').onsubmit=async event=>{ event.preventDefault(); const form=event.currentTarget, error=quoteModal.querySelector('.quote-error'), submit=form.querySelector('button[type="submit"]'); submit.disabled=true; error.classList.add('hidden'); try { const response=await fetch(@json(route('items.quote-requests.store',$item->slug)),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':@json(csrf_token())},body:JSON.stringify({name:form.name.value,email:form.email.value,company:form.company.value,message:form.message.value,configuration:configurationState()})}); if(!response.ok)throw new Error('Request could not be sent'); form.innerHTML='<div class="py-8 text-center"><div class="text-4xl text-emerald-300">✓</div><h2 class="mt-3 text-xl font-medium text-white">Request received</h2><p class="mt-2 text-sm text-slate-400">Our team will review your configuration and contact you soon.</p></div>'; } catch(exception) { error.textContent='Please check your details and try again.'; error.classList.remove('hidden'); submit.disabled=false; } };
document.querySelector('#apply-color').onclick=()=>{ selectedMaterials().forEach(material=>material.color?.set(document.querySelector('#color').value)); };
document.querySelector('#clear-texture')?.addEventListener('click',()=>{ selectedMaterials().forEach(material=>{material.map=null;material.needsUpdate=true;}); document.querySelector('#clear-texture')?.classList.add('hidden'); });
document.querySelector('#reset').onclick=()=>{ camera.position.copy(originalCamera); controls.target.set(0,.7,0); controls.update(); isolated=false; exploded=false; modelParts.forEach(part=>part.visible=true); setExplode(0); viewerTools.querySelector('#isolate-part').textContent='Isolate selected'; viewerTools.querySelector('#explode-model').classList.remove('bg-cyan-300/20'); };
function configurationState(){ return { version:1, item:'{{ $item->slug }}', parts:modelParts.map((part,index)=>({ index, visible:part.visible, materials:(Array.isArray(part.material)?part.material:[part.material]).map(material=>({ color:material.color?.getHexString(), texture:material.userData.appliedTextureUrl||null })) })) }; }
function encodeConfiguration(state){ return btoa(unescape(encodeURIComponent(JSON.stringify(state)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); }
function decodeConfiguration(value){ try { const padded=value.replace(/-/g,'+').replace(/_/g,'/')+'==='.slice((value.length+3)%4); return JSON.parse(decodeURIComponent(escape(atob(padded)))); } catch(error) { console.error('Invalid model configuration',error); return null; } }
async function saveConfiguration(){ const state=configurationState(); localStorage.setItem('model-config-{{ $item->slug }}',JSON.stringify(state)); const response=await fetch(@json(route('items.configurations.store',$item->slug)),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':@json(csrf_token())},body:JSON.stringify({name:'My configuration',configuration:state})}); if(!response.ok)throw new Error('Configuration could not be saved'); const data=await response.json(); const button=document.querySelector('#save-config'); button.textContent='Configuration saved'; setTimeout(()=>button.textContent='Save configuration',1800); return data; }
async function loadServerConfiguration(token){ try { const response=await fetch(@json(route('items.configurations.show',[$item->slug,'CONFIGURATION_TOKEN'])).replace('CONFIGURATION_TOKEN',encodeURIComponent(token)),{headers:{'Accept':'application/json'}}); return response.ok?await response.json():null; } catch(error) { console.error('Configuration could not be loaded',error); return null; } }
async function shareConfiguration(){ try { const data=await saveConfiguration(); await navigator.clipboard.writeText(data.url); const button=document.querySelector('#share-config'); button.textContent='Link copied'; setTimeout(()=>button.textContent='Share configuration',1800); } catch(error) { const url=new URL(window.location.href); url.hash='config='+encodeConfiguration(configurationState()); window.prompt('Copy this configuration link:',url.toString()); } }
function restoreConfiguration(state){ if(!state?.parts)return; state.parts.forEach(saved=>{ const part=modelParts[saved.index]; if(!part)return; part.visible=saved.visible!==false; const materials=Array.isArray(part.material)?part.material:[part.material]; saved.materials?.forEach((materialState,index)=>{ const material=materials[index]; if(!material)return; if(materialState.color&&material.color)material.color.set('#'+materialState.color); if(materialState.texture)new THREE.TextureLoader().load(materialState.texture,texture=>{ texture.colorSpace=THREE.SRGBColorSpace; texture.wrapS=texture.wrapT=THREE.RepeatWrapping; material.map=texture; material.userData.appliedTextureUrl=materialState.texture; material.needsUpdate=true; }); }); }); }
function setExplode(amount){ if(!model)return; modelParts.forEach(part=>{ part.position.copy(part.userData.originalPosition); if(amount){ const direction=part.userData.explodeDirection||new THREE.Vector3((part.position.x||0)+.1,(part.position.y||0)+.1,(part.position.z||0)+.1).normalize(); part.position.addScaledVector(direction,amount); } }); }
viewerTools.querySelector('#auto-rotate').onclick=event=>{ autoRotate=!autoRotate; event.currentTarget.classList.toggle('bg-cyan-300/20',autoRotate); };
viewerTools.querySelector('#isolate-part').onclick=()=>{ if(!selectedParts.length){ alert('Select a model part first.'); return; } isolated=!isolated; modelParts.forEach(part=>part.visible=!isolated||selectedParts.includes(part)); viewerTools.querySelector('#isolate-part').textContent=isolated?'Show all parts':'Isolate selected'; };
viewerTools.querySelector('#explode-model').onclick=event=>{ exploded=!exploded; setExplode(exploded ? .45 : 0); event.currentTarget.classList.toggle('bg-cyan-300/20',exploded); };
viewerTools.querySelector('#save-config').onclick=saveConfiguration;
viewerTools.querySelector('#share-config').onclick=shareConfiguration;
document.querySelector("#fullscreen").onclick=()=>{ document.fullscreenElement ? document.exitFullscreen() : stage.requestFullscreen?.(); }; document.querySelector("#share").onclick=async()=>{ try { if(navigator.share){ await navigator.share({title:document.title,url:window.location.href}); } else { await navigator.clipboard.writeText(window.location.href); const button=document.querySelector("#share"); button.textContent="Link copied"; setTimeout(()=>button.textContent="Share",1800); } } catch(error) { if(error.name !== "AbortError") console.error(error); } }; function download(type){ const link=document.createElement('a'); link.download='{{ $item->slug }}.'+(type==='image/jpeg'?'jpg':'png'); link.href=renderer.domElement.toDataURL(type,.92); link.click(); } document.querySelector('#png').onclick=()=>download('image/png'); document.querySelector('#jpeg').onclick=()=>download('image/jpeg');
</script></body></html>
